def compare(a,b,path,base,n):
 if isinstance(a,dict) and isinstance(b,dict):
  for k in sorted(a.keys()&b.keys()):compare(a[k],b[k],path+'.'+k,base,n)
 elif isinstance(a,list) and isinstance(b,list) and len(a)==len(b):
  for i,(x,y) in enumerate(zip(a,b)):compare(x,y,f'{path}[{i}]',base,n)
 elif isinstance(a,(int,float)) and isinstance(b,(int,float)) and not isinstance(a,bool) and not isinstance(b,bool) and math.isfinite(a) and math.isfinite(b) and a!=b:changes.append(dict(previous_revision=base,notebook=n,field=path,previous=a,cloud=b,delta=b-a,execution_commit=R[n]['execution_commit']))
