  p='results/'+R[n]['notebook']+'.json';r=subprocess.run(['git','show',ref+':'+p],cwd=root,capture_output=True,text=True)
  if r.returncode==0:
   old=json.loads(r.stdout);previous[(name,n)]=old;compare(old,R[n],'',name,n)
